#!/bin/sh
R=/home/user/settlement-engine
snap(){ git -C $R for-each-ref --format='%(refname) %(objectname)' > /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/refs.$1; git -C $R config --local --list > /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/cfg.$1; }
until grep -q SUITES-DONE /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/gates/suites.log; do sleep 15; done
snap pre
python3 /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/probes/plant.py /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/wt/p-a /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/probes/plants-A.json /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/A.json > /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/A.txt 2>&1
python3 /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/probes/plant.py /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/wt/p-b /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/probes/plants-B.json /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/B.json > /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/B.txt 2>&1
python3 /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/probes/plant.py /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/wt/p-c /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/probes/plants-C.json /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/C.json > /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/C.txt 2>&1
snap post; cmp -s /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/refs.pre /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/refs.post && cmp -s /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/cfg.pre /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/cfg.post && echo "PLANT SNAP same" || echo "PLANT SNAP CHANGED"
echo PLANTS-DONE $(date -u +%T)
for t in c-base c-tip b-tip ab-base a-tip; do sh /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/census-tool/census.sh /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/wt/$t /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/c720/$t 4 > /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/c720/$t.log 2>&1; echo "census $t EXIT=$? $(date -u +%T)"; done
snap post2; cmp -s /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/refs.pre /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/refs.post2 && cmp -s /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/cfg.pre /tmp/claude-0/-home-user-settlement-engine/ed9a7fac-3574-5fcd-a762-3429f90b7a9d/scratchpad/plants/cfg.post2 && echo "CENSUS SNAP same" || echo "CENSUS SNAP CHANGED"
echo AFTER-DONE
